import{i as e,r as t,s as n,t as r}from"./app-DuH0mZgh.js";var i=JSON.parse(`{"path":"/30-Compact_GameServer_Design.html","title":"Compact GameServer 设计方案（塔防/固定地图适配）","lang":"en-US","frontmatter":{},"filePathRelative":"30-Compact_GameServer_Design.md","git":{"createdTime":1765122601000,"updatedTime":1765122601000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`30-Compact_GameServer_Design.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="compact-gameserver-设计方案-塔防-固定地图适配" tabindex="-1"><a class="header-anchor" href="#compact-gameserver-设计方案-塔防-固定地图适配"><span>Compact GameServer 设计方案（塔防/固定地图适配）</span></a></h1><blockquote><p>目的：在通用 MMO 架构基础上，为塔防、绿色循环圈等固定地图、轻量玩法提供精简版 GameServer 形态，复用现有基础设施但减少服务拆分成本。</p></blockquote><h2 id="_1-场景与需求" tabindex="-1"><a class="header-anchor" href="#_1-场景与需求"><span>1. 场景与需求</span></a></h2><ul><li>地图数有限（1~数十），每张地图玩家数较少（&lt;200）。</li><li>缺乏动态场景/副本调度，更多是波次、防守类玩法。</li><li>可接受单进程内处理 AOI/战斗/场景逻辑，降低运维复杂度。</li><li>仍希望保留 NetCore、DataProxy、配置、插件、监控、SDK 等统一能力，未来可平滑升级到 MMO 模式。</li></ul><h2 id="_2-架构对比" tabindex="-1"><a class="header-anchor" href="#_2-架构对比"><span>2. 架构对比</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">MMO 模式: Gate -&gt; World -&gt; Scene Orchestrator -&gt; Zone + AOI + Battle</span>
<span class="line">Compact 模式: Gate -&gt; Compact GameServer (Scene + AOI + Battle in one)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Compact GameServer 仍通过 Transport/Registry 与其他服务交互（DataProxy、Social、LogAgent 等）。</p><h2 id="_3-模块合并策略" tabindex="-1"><a class="header-anchor" href="#_3-模块合并策略"><span>3. 模块合并策略</span></a></h2><table><thead><tr><th>模块</th><th>MMO 模式</th><th>Compact 模式说明</th></tr></thead><tbody><tr><td>Scene Orchestrator</td><td>独立服务</td><td>合并进 Compact GS 的 SceneManager，维护固定地图实例表</td></tr><tr><td>ZoneServer</td><td>多实例/多进程</td><td>以线程或协程形式运行，按地图分线程；可配置一个进程内多个逻辑实例</td></tr><tr><td>AOI Service</td><td>独立集群</td><td>使用内嵌 AOI 模块（与 Zone 同进程共享 AOIManager），仍可分 shard</td></tr><tr><td>Battle Service</td><td>可选独立</td><td>作为内部模块；大型战斗时可仍调用外部 Battle Service</td></tr><tr><td>Transport</td><td>AOI/Zone 互通</td><td>Compact 模式可禁用 AOI↔Zone Transport，保留与 Gate/DataProxy 的管道</td></tr><tr><td>WorldServer</td><td>全局调度</td><td>若玩法简单，可由单个 Compact GS 管理/或保留轻量 World 处理账号/匹配</td></tr></tbody></table><h2 id="_4-compact-gameserver-结构" tabindex="-1"><a class="header-anchor" href="#_4-compact-gameserver-结构"><span>4. Compact GameServer 结构</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">CompactGameServer</span>
<span class="line"> ├─ NetEndpoint (与 Gate 通信)</span>
<span class="line"> ├─ SceneManager</span>
<span class="line"> │    └─ SceneInstance (固定地图)</span>
<span class="line"> │         ├─ AOIManager (嵌入)</span>
<span class="line"> │         ├─ BattleModule</span>
<span class="line"> │         ├─ WaveManager (塔防特有)</span>
<span class="line"> │         └─ ScriptEngine (Lua)</span>
<span class="line"> ├─ PlayerManager</span>
<span class="line"> ├─ DataProxyClient</span>
<span class="line"> ├─ SocialClient / TransportAdapter</span>
<span class="line"> └─ Monitoring/Config/Plugin</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>SceneManager 维护一张 <code>scene_config</code> 表（map_id、最大玩家、波次配置）。</li><li>每个 SceneInstance 运行自己的 Tick，负责单位刷新、波次、建塔、Buff 等。</li><li>AOIManager 使用与独立 AOI 一致的数据结构，但不再跨进程；若未来需要扩展，可将 AOI 接口保留，切换到远程实现。</li></ul><h2 id="_5-线程与扩展" tabindex="-1"><a class="header-anchor" href="#_5-线程与扩展"><span>5. 线程与扩展</span></a></h2><ul><li>推荐配置：单机多线程，按地图类型划分线程池。例如 4 核机器运行 4 个 Scene Thread，每个线程管理若干地图。</li><li>支持多实例部署：每个 Compact GS 可负责一组地图；通过 Consul 注册 <code>map_range</code>，Gate/World 根据玩家地图路由到对应实例。</li><li>若需要水平扩容（更多玩家/地图），可再部署多个 Compact GS 或升级为完整 Zone/AOI 分层。</li></ul><h2 id="_6-数据和配置" tabindex="-1"><a class="header-anchor" href="#_6-数据和配置"><span>6. 数据和配置</span></a></h2><ul><li>玩家数据仍通过 DataProxy 访问；Compact 模式只需在 Scene 中处理临时状态。</li><li>配置热更新流程与主框架一致；塔防特有配置（波次、塔属性、敌人路径）放在配置系统 Excel/Lua 中。</li><li>属性/IDL 同样使用统一生成工具 (<code>docs/22</code>)。</li></ul><h2 id="_7-对-gate-sdk-的影响" tabindex="-1"><a class="header-anchor" href="#_7-对-gate-sdk-的影响"><span>7. 对 Gate/SDK 的影响</span></a></h2><ul><li>Gate 仍按会话将玩家转发到对应 <code>CompactGameServer</code>。</li><li>SDK/客户端协议完全一致；只是逻辑服务器 fewer hops，延迟更低。</li><li>坐标/状态同步的消息流与 MMO 模式相同，便于客户端复用。</li></ul><h2 id="_8-迁移与升级" tabindex="-1"><a class="header-anchor" href="#_8-迁移与升级"><span>8. 迁移与升级</span></a></h2><ul><li>如果未来地图/玩法扩展，需要独立 AOI/Scene 服务，只需： <ol><li>将 SceneManager/ AOI 模块抽出为服务。</li><li>Gate/World 路由逻辑不变。</li><li>Compact 模式中的 Scene/AOI 接口已与独立版本一致，迁移成本低。</li></ol></li></ul><h2 id="_9-监控与运维" tabindex="-1"><a class="header-anchor" href="#_9-监控与运维"><span>9. 监控与运维</span></a></h2><ul><li>关键指标：每张地图玩家数、帧耗时、AOI 事件数、波次处理时间、战斗结算耗时。</li><li>失败策略：单实例异常时，World/Gate 将玩家路由到备用实例，或回滚至主城。</li><li>支持平滑重启：Scene 状态可序列化（保存当前波次、敌人状态），重启后恢复。</li></ul><h2 id="_10-roadmap" tabindex="-1"><a class="header-anchor" href="#_10-roadmap"><span>10. Roadmap</span></a></h2><ol><li>实现 Compact GameServer 核心框架（SceneManager + AOI + Battle 内嵌）。</li><li>集成 NetCore/Transport/DataProxy/插件/配置等现有模块。</li><li>打通塔防玩法（波次、建塔、技能）示例，验证端到端流程。</li><li>监控和运维方案与主框架共享，补充塔防特有指标。</li><li>预留接口以便未来升级到完整 Zone/AOI 分层。</li></ol><hr><p>该设计让框架既能服务大型 MMO，也能用更轻的形态覆盖塔防或固定地图游戏，保持后续演进空间。***</p>`,26)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};